function build_oracle_v0_1
% Build deterministic 8-connected regional-extrema oracle cases.
% The reference masks are generated by MATLAB Image Processing Toolbox
% imregionalmax/imregionalmin with explicit 8-connectivity.

scriptDir = fileparts(mfilename('fullpath'));
outDir = fullfile(scriptDir, 'oracle_v0_1');
caseDir = fullfile(outDir, 'cases');
inputDir = fullfile(outDir, 'inputs');
inputPngDir = fullfile(outDir, 'inputs_png');
maxDir = fullfile(outDir, 'expected_max');
minDir = fullfile(outDir, 'expected_min');
if ~exist(caseDir, 'dir')
    mkdir(caseDir);
end
if ~exist(inputDir, 'dir')
    mkdir(inputDir);
end
if ~exist(inputPngDir, 'dir')
    mkdir(inputPngDir);
end
if ~exist(maxDir, 'dir')
    mkdir(maxDir);
end
if ~exist(minDir, 'dir')
    mkdir(minDir);
end

cases = {};

cases{end + 1} = make_case('constant_5x5', uint8(7 * ones(5, 5)));
cases{end + 1} = make_case('singleton_1x1', uint8(11));

img = uint8(ones(5, 5));
img(3, 3) = 2;
cases{end + 1} = make_case('single_peak_5x5', img);

img = uint8(2 * ones(5, 5));
img(3, 3) = 1;
cases{end + 1} = make_case('single_pit_5x5', img);

img = uint8(2 * ones(7, 7));
img(3:5, 3:5) = 8;
cases{end + 1} = make_case('interior_max_plateau_7x7', img);

img = uint8(8 * ones(7, 7));
img(3:5, 3:5) = 2;
cases{end + 1} = make_case('interior_min_plateau_7x7', img);

img = uint8(2 * ones(7, 7));
img(1:2, 1:3) = 8;
cases{end + 1} = make_case('border_max_plateau_7x7', img);

img = uint8(2 * ones(7, 7));
img(2, 2) = 8;
img(3, 3) = 8;
img(4, 4) = 8;
cases{end + 1} = make_case('diagonal_max_plateau_7x7', img);

img = uint8(5 * ones(7, 7));
img(3:5, 3:5) = 6;
img(2, 4) = 7;
img(6, 4) = 4;
cases{end + 1} = make_case('saddle_non_extreme_7x7', img);

img = uint8(2 * ones(9, 9));
img(2:8, 2:8) = 7;
img(3:7, 3:7) = 4;
img(4:6, 4:6) = 9;
img(5, 5) = 1;
cases{end + 1} = make_case('nested_rings_9x9', img);

img = uint8(2 * ones(17, 17));
img(4:14, 8:10) = 8;
img(9, 4:14) = 8;
cases{end + 1} = make_case('tile_crossing_max_17x17', img);

[yy, xx] = ndgrid(1:8, 1:8);
img = uint8(mod(xx + yy, 2) * 255);
cases{end + 1} = make_case('checkerboard_8x8', img);

img = repmat(uint8(0:15), 9, 1);
cases{end + 1} = make_case('horizontal_ramp_9x16', img);

img = uint8(4 * ones(1, 17));
img(1, 4:7) = 9;
img(1, 11:14) = 1;
cases{end + 1} = make_case('line_plateaus_1x17', img);

rng(20260728, 'twister');
for idx = 1:20
    img = uint8(randi([0, 7], 16, 16));
    cases{end + 1} = make_case(sprintf('random_q8_%02d', idx), img);
end

n = numel(cases);
ids = strings(n, 1);
heights = zeros(n, 1);
widths = zeros(n, 1);
maxPixels = zeros(n, 1);
minPixels = zeros(n, 1);
maxComponents = zeros(n, 1);
minComponents = zeros(n, 1);
extremeUnionPixels = zeros(n, 1);
extremePlateauCount = zeros(n, 1);

for idx = 1:n
    item = cases{idx};
    maxMask = imregionalmax(item.image, 8);
    minMask = imregionalmin(item.image, 8);
    maxCC = bwconncomp(maxMask, 8);
    minCC = bwconncomp(minMask, 8);
    overlapCC = bwconncomp(maxMask & minMask, 8);

    ids(idx) = string(item.id);
    [heights(idx), widths(idx)] = size(item.image);
    maxPixels(idx) = nnz(maxMask);
    minPixels(idx) = nnz(minMask);
    maxComponents(idx) = maxCC.NumObjects;
    minComponents(idx) = minCC.NumObjects;
    extremeUnionPixels(idx) = nnz(maxMask | minMask);
    extremePlateauCount(idx) = ...
        maxCC.NumObjects + minCC.NumObjects - overlapCC.NumObjects;

    imwrite(item.image, fullfile(caseDir, [item.id, '_input.pgm']));
    imwrite(uint8(maxMask) * 255, fullfile(caseDir, [item.id, '_max.pgm']));
    imwrite(uint8(minMask) * 255, fullfile(caseDir, [item.id, '_min.pgm']));
    imwrite(item.image, fullfile(inputDir, [item.id, '.pgm']));
    imwrite(item.image, fullfile(inputPngDir, [item.id, '.png']));
    imwrite(uint8(maxMask) * 255, fullfile(maxDir, [item.id, '.pgm']));
    imwrite(uint8(minMask) * 255, fullfile(minDir, [item.id, '.pgm']));
end

manifest = table( ...
    ids, heights, widths, maxPixels, minPixels, maxComponents, minComponents, ...
    extremeUnionPixels, extremePlateauCount, ...
    'VariableNames', { ...
        'case_id', 'height', 'width', 'max_pixels', 'min_pixels', ...
        'max_components_8c', 'min_components_8c', ...
        'extreme_union_pixels', 'extreme_plateau_count_union' ...
    } ...
);
writetable(manifest, fullfile(outDir, 'oracle_manifest.csv'));

readmePath = fullfile(outDir, 'README.txt');
fid = fopen(readmePath, 'w');
assert(fid >= 0, 'Could not open README for writing.');
cleanup = onCleanup(@() fclose(fid));
fprintf(fid, 'Regional-extrema oracle v0.1\n');
fprintf(fid, 'Generated with MATLAB %s.\n', version);
fprintf(fid, 'Reference: imregionalmax(image, 8) and imregionalmin(image, 8).\n');
fprintf(fid, 'Masks are full-plateau pixel masks stored as 0/255 PGM files.\n');
fprintf(fid, 'Constant-domain convention follows MATLAB: inspect manifest counts before adapting C++ baselines.\n');
fprintf(fid, 'Random seed: 20260728; random_q8 cases use values 0..7.\n');

disp(manifest(1:14, :));
fprintf('[ORACLE-BUILD-OK] cases=%d output=%s\n', n, outDir);
end

function item = make_case(id, image)
item = struct('id', id, 'image', image);
end
